    -d.x * d.x * s * sin(f),
    d.x * s * cos(f),
    -d.x * d.y * s * sin(f)
  );
  binormal += vec3(
    -d.x * d.y * s * sin(f),
    d.y * s * cos(f),
    -d.y * d.y * s * sin(f)
  );
