  vec4 alphaBlend(vec4 top, vec4 bottom)
{
  vec3 color = (top.rgb * top.a) + (bottom.rgb * (1. - top.a));
  float alpha = top.a + bottom.a * (1. - top.a);
  return vec4(color, alpha);
}
